import { tagsCreate, tagsDestroy, tagsPinnedList } from '~/generated/core/api'
import type { TagApi } from '~/generated/core/api.schemas'

/** The same normalization as `tagify` in posthog/models/tag.py, so the modal can tell an existing tag from a new one. */
export function normalizeTagName(name: string): string {
    return name.trim().toLowerCase()
}

