/**
 * The project's pinned tags: the tags people create on purpose in the "Manage tags" modal, which are
 * the only ones the workflows table offers when tagging a workflow.
 */
export const workflowTagsLogic = kea<workflowTagsLogicType>([
    path(['products', 'workflows', 'frontend', 'workflowTagsLogic']),
    actions({
        openManageTagsModal: true,
        closeManageTagsModal: true,
        setNewTagName: (name: string) => ({ name }),
        createTag: (name: string) => ({ name }),
        deleteTag: (tag: TagApi) => ({ tag }),
    }),
    reducers({
        isManageTagsModalOpen: [
            false,
            {
                openManageTagsModal: () => true,
                closeManageTagsModal: () => false,
            },
        ],
        newTagName: [
            '',
            {
                setNewTagName: (_, { name }) => name,
                createTagSuccess: () => '',
                closeManageTagsModal: () => '',
            },
        ],
    }),
    loaders(({ values }) => ({
        pinnedTags: [
            // null until the first load answers, so the modal can tell "loading" from "no tags yet".
            null as TagApi[] | null,
            {
                loadPinnedTags: async () => await tagsPinnedList(String(ApiConfig.getCurrentProjectId())),
                createTag: async ({ name }) => {
                    const tag = await tagsCreate(String(ApiConfig.getCurrentProjectId()), { name })
                    // The server pins an existing tag instead of creating a second one, so replace by id.
                    const others = (values.pinnedTags ?? []).filter((existing) => existing.id !== tag.id)
                    return [...others, tag].sort((a, b) => a.name.localeCompare(b.name))
                },
                deleteTag: async ({ tag }) => {
                    await tagsDestroy(String(ApiConfig.getCurrentProjectId()), tag.id)
                    return (values.pinnedTags ?? []).filter((existing) => existing.id !== tag.id)
                },
            },
        ],
    })),
    selectors({
        pinnedTagNames: [
            (s) => [s.pinnedTags],
            (pinnedTags: TagApi[] | null): string[] => (pinnedTags ?? []).map((tag) => tag.name),
        ],
        normalizedNewTagName: [(s) => [s.newTagName], (newTagName: string): string => normalizeTagName(newTagName)],
        matchingTags: [
            (s) => [s.pinnedTags, s.normalizedNewTagName],
            (pinnedTags: TagApi[] | null, normalizedNewTagName: string): TagApi[] =>
                (pinnedTags ?? []).filter((tag) => tag.name.includes(normalizedNewTagName)),
        ],
        newTagExists: [
            (s) => [s.pinnedTagNames, s.normalizedNewTagName],
            (pinnedTagNames: string[], normalizedNewTagName: string): boolean =>
                pinnedTagNames.includes(normalizedNewTagName),
        ],
    }),
    listeners({
        loadPinnedTagsFailure: ({ error }) => {
            lemonToast.error(`Failed to load tags: ${error || 'Unknown error'}`)
        },
        createTagFailure: ({ error }) => {
            lemonToast.error(`Failed to create tag: ${error || 'Unknown error'}`)
        },
        deleteTagFailure: ({ error }) => {
            lemonToast.error(`Failed to remove tag: ${error || 'Unknown error'}`)
        },
    }),
])
